import { AfterViewInit, Component, ElementRef, OnDestroy, ViewChild, ViewEncapsulation } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-active-tender',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './active-tender.component.html',
  styleUrl: './active-tender.component.css',
  encapsulation: ViewEncapsulation.None
})
export class ActiveTenderComponent implements AfterViewInit, OnDestroy {
  @ViewChild('activeTenderRoot', { static: true })
  private activeTenderRoot!: ElementRef<HTMLElement>;

  private initialized = false;
  private originalBodyClass = '';

  private readonly pageScriptBase64 = '';

  ngAfterViewInit(): void {
    if (this.initialized) return;
    this.initialized = true;
    this.originalBodyClass = document.body.className;
    document.body.classList.add('active-tender-body');

    window.setTimeout(() => {
      new Function(this.decodePageScript()).call(window);
    });
  }

  ngOnDestroy(): void {
    document.body.className = this.originalBodyClass;
    this.activeTenderRoot.nativeElement.replaceChildren();
  }

  goTo(path: string): void {
    window.location.href = path;
  }

  private decodePageScript(): string {
    const binary = window.atob(this.pageScriptBase64);
    const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
    return new TextDecoder().decode(bytes);
  }
}
